<?php
require __DIR__.'/config.php';
$count=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();$message='';
if($_SERVER['REQUEST_METHOD']==='POST'&&$count===0){
if(!hash_equals(csrf_token(),$_POST['csrf']??'')){http_response_code(419);exit('Security token expired. Refresh this page.');}
$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pw=(string)($_POST['password']??'');
if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&strlen($pw)>=12){try{$st=$pdo->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'admin')");$st->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);$message='Administrator created. Delete setup_admin.php immediately, then sign in at admin.php.';$count=1;}catch(Throwable $e){$message='Could not create account; check whether the email is already used.';}}else $message='Enter a name, valid email and password with at least 12 characters.';
}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Initial admin setup</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-100 p-5"><main class="bg-white rounded-2xl shadow p-7 max-w-lg mx-auto mt-10"><h1 class="text-2xl font-black mb-4">Create first administrator</h1><?php if($message):?><p class="bg-amber-100 p-3 rounded mb-4"><?=e($message)?></p><?php endif;?><?php if(!$count):?><form method="post" class="space-y-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input name="name" required class="border rounded p-3 w-full" placeholder="Full name"><input name="email" type="email" required class="border rounded p-3 w-full" placeholder="Admin email"><input name="password" type="password" minlength="12" required class="border rounded p-3 w-full" placeholder="Password (12+ characters)"><button class="bg-orange-500 text-white rounded p-3 w-full font-bold">Create administrator</button></form><?php else:?><p>Administrator exists. Delete this setup file now.</p><?php endif;?></main></body></html>